package usuariosroles.repositories;

import java.util.List;
import java.util.Optional;
import org.springframework.data.repository.CrudRepository;
import org.springframework.stereotype.Repository;
import usuariosroles.entities.Rol;

/**
 * Spring Data JPA repository for the {@link Rol} entity.
 *
 * <p>Provides basic CRUD operations inherited from {@link CrudRepository}
 * and custom query methods to retrieve roles based on specific criteria.</p>
 *
 * <p>The implementation of this interface is automatically generated by Spring Data
 * based on the declared method signatures.</p>
 *
 * @author Daniel
 * @version 1.0
 */
@Repository
public interface RolRepository extends CrudRepository<Rol, Integer> {

    /**
     * Finds all roles by their active status.
     *
     * @param activo Active status of the role ({@code true} = active, {@code false} = inactive).
     * @return List of roles matching the criteria.
     */
    List<Rol> findAllByActivo(Boolean activo);

    /**
     * Finds a role by its name and active status.
     *
     * @param nombreRol Name of the role.
     * @param activo Active status of the role.
     * @return {@link Optional} containing the role if found, or empty if not found.
     */
    Optional<Rol> findByNombreRolAndActivo(String nombreRol, Boolean activo);

    /**
     * Finds a role by its name.
     *
     * @param nombreRol Name of the role.
     * @return {@link Optional} containing the role if found, or empty if not found.
     */
    Optional<Rol> findByNombreRol(String nombreRol);

    /**
     * Finds a role by its identifier and active status.
     *
     * @param idRol Role identifier.
     * @param activo Active status of the role.
     * @return {@link Optional} containing the role if found, or empty if not found.
     */
    Optional<Rol> findByIdRolAndActivo(Integer idRol, Boolean activo);

    /**
     * Checks if a role exists with a specific name.
     *
     * @param nombreRol Name of the role.
     * @return {@code true} if it exists, {@code false} otherwise.
     */
    boolean existsByNombreRol(String nombreRol);

    /**
     * Checks if a role exists with a specific name and active status.
     *
     * @param nombreRol Name of the role.
     * @param activo Active status of the role.
     * @return {@code true} if it exists, {@code false} otherwise.
     */
    boolean existsByNombreRolAndActivo(String nombreRol, Boolean activo);
}
